pub trait TextAccess { fn words(&self) -> Vec<String>; }   // behaviour
impl TextAccess for Document {                              // type untouched
    fn words(&self) -> Vec<String> { split_words(&self.text) }
}

pub struct Extensions(HashMap<TypeId, Box<dyn Any>>);       // attached state
impl Extensions {
    pub fn insert<T: 'static>(&mut self, v: T) { self.0.insert(TypeId::of::<T>(), Box::new(v)); }
    pub fn get<T: 'static>(&self) -> Option<&T> {           // None == absent
        self.0.get(&TypeId::of::<T>()).and_then(|b| b.downcast_ref())
    }
}
